from itertools import permutations

def solve_logic_puzzle():
    people = ['Harper', 'Jordan', 'Quinn', 'Riley', 'Sawyer']
    colors = ['blue', 'green', 'orange', 'white', 'yellow']
    pets = ['bird', 'cat', 'dog', 'horse', 'rabbit']
    drinks = ['coffee', 'juice', 'milk', 'tea', 'water']
    hobbies = ['baking', 'chess', 'fencing', 'hiking', 'painting']

    def is_valid_solution(assignment):
        # assignment is list of 5 tuples: (person, color, pet, drink, hobby)

        # Create position lookups
        pos = {assignment[i][0]: i for i in range(5)}

        def get_attr(person, attr_idx):
            return assignment[pos[person]][attr_idx]

        def color_of(person):
            return get_attr(person, 1)

        def pet_of(person):
            return get_attr(person, 2)

        def drink_of(person):
            return get_attr(person, 3)

        def hobby_of(person):
            return get_attr(person, 4)

        def person_at(idx):
            return assignment[idx][0]

        def immediately_left(p1, p2):
            return pos[p1] == pos[p2] - 1

        def next_to(p1, p2):
            return abs(pos[p1] - pos[p2]) == 1

        # Check all 16 clues
        # 1. White house person is not Sawyer
        if color_of('Sawyer') == 'white':
            return False

        # 2. Orange house person does hiking
        for p in people:
            if color_of(p) == 'orange' and hobby_of(p) != 'hiking':
                return False
            if hobby_of(p) == 'hiking' and color_of(p) != 'orange':
                return False

        # 3. Horse owner immediately left of tea drinker
        for p in people:
            if drink_of(p) == 'tea':
                tea_pos = pos[p]
                if tea_pos == 0 or pet_of(person_at(tea_pos - 1)) != 'horse':
                    return False

        # 4. Milk drinker not in orange house
        for p in people:
            if drink_of(p) == 'milk' and color_of(p) == 'orange':
                return False

        # 5. Jordan next to blue house
        for p in people:
            if color_of(p) == 'blue':
                if not next_to('Jordan', p):
                    return False

        # 6. Juice drinker does chess
        for p in people:
            if drink_of(p) == 'juice' and hobby_of(p) != 'chess':
                return False
            if hobby_of(p) == 'chess' and drink_of(p) != 'juice':
                return False

        # 7. Horse owner immediately left of blue house
        for p in people:
            if color_of(p) == 'blue':
                blue_pos = pos[p]
                if blue_pos == 0:
                    return False
                if pet_of(person_at(blue_pos - 1)) != 'horse':
                    return False

        # 8. Harper drinks tea
        if drink_of('Harper') != 'tea':
            return False

        # 9. Jordan not in orange house
        if color_of('Jordan') == 'orange':
            return False

        # 10. Sawyer next to cat owner
        sawyer_pos = pos['Sawyer']
        cat_next = False
        if sawyer_pos > 0 and pet_of(person_at(sawyer_pos - 1)) == 'cat':
            cat_next = True
        if sawyer_pos < 4 and pet_of(person_at(sawyer_pos + 1)) == 'cat':
            cat_next = True
        if not cat_next:
            return False

        # 11. Bird owner immediately left of green house
        for i in range(1, 5):
            if color_of(person_at(i)) == 'green':
                if pet_of(person_at(i - 1)) != 'bird':
                    return False

        # 12. Riley immediately left of baking person
        riley_pos = pos['Riley']
        if riley_pos >= 4:
            return False
        if hobby_of(person_at(riley_pos + 1)) != 'baking':
            return False

        # 13. Quinn immediately left of tea drinker
        if not immediately_left('Quinn', 'Harper'):
            return False

        # 14. Fencing person next to orange house
        for i in range(5):
            if color_of(person_at(i)) == 'orange':
                orange_pos = i
                fencing_next = False
                if orange_pos > 0 and hobby_of(person_at(orange_pos - 1)) == 'fencing':
                    fencing_next = True
                if orange_pos < 4 and hobby_of(person_at(orange_pos + 1)) == 'fencing':
                    fencing_next = True
                if not fencing_next:
                    return False

        # 15. Rabbit owner next to orange house
        for i in range(5):
            if color_of(person_at(i)) == 'orange':
                orange_pos = i
                rabbit_next = False
                if orange_pos > 0 and pet_of(person_at(orange_pos - 1)) == 'rabbit':
                    rabbit_next = True
                if orange_pos < 4 and pet_of(person_at(orange_pos + 1)) == 'rabbit':
                    rabbit_next = True
                if not rabbit_next:
                    return False

        # 16. Water drinker immediately left of green house
        for i in range(1, 5):
            if color_of(person_at(i)) == 'green':
                if drink_of(person_at(i - 1)) != 'water':
                    return False

        return True

    # Brute force search
    for people_perm in permutations(people):
        for color_perm in permutations(colors):
            for pet_perm in permutations(pets):
                for drink_perm in permutations(drinks):
                    for hobby_perm in permutations(hobbies):
                        assignment = list(zip(people_perm, color_perm, pet_perm, drink_perm, hobby_perm))
                        if is_valid_solution(assignment):
                            # Find who lives in blue house
                            for person, color, pet, drink, hobby in assignment:
                                if color == 'blue':
                                    return person

    return "UNKNOWN"

answer = solve_logic_puzzle()
print(f"ANSWER: {answer}")
